<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {House,User,Calendar,DocumentChecked,Link,Setting,SwitchButton,ArrowRight,Refresh,Sunny} from '@element-plus/icons-vue';
import {api,auth,restoreAuth,logout as signOut,authScope,isCurrentAuth,assertCurrentAuth,isStaleAuthError,dateTime,taskLabel} from './api';import LoginPanel from './components/LoginPanel.vue';import PatientWorkspace from './components/PatientWorkspace.vue';import BindingWorkspace from './components/BindingWorkspace.vue';import TaskWorkspace from './components/TaskWorkspace.vue';import ReviewWorkspace from './components/ReviewWorkspace.vue';
const view=ref('dashboard');const refreshKey=ref(0);const reviewId=ref('');const patients=ref<any[]>([]);const tasks=ref<any[]>([]);const reviews=ref<any[]>([]);const bindings=ref<any[]>([]);const health=ref<any>(null);const capabilities=ref<any>(null);const protocol=ref<any>(null);
const nav=[{id:'dashboard',label:'工作台',icon:House},{id:'patients',label:'患者管理',icon:User},{id:'tasks',label:'随访计划',icon:Calendar},{id:'reviews',label:'随访审核',icon:DocumentChecked},{id:'bindings',label:'既有绑定申请',icon:Link},{id:'settings',label:'服务状态',icon:Setting}];
const pendingReviews=computed(()=>reviews.value.filter(r=>r.review_status!=='reviewed'));const pendingTasks=computed(()=>tasks.value.filter(t=>['pending','in_progress'].includes(t.status)));const overdue=computed(()=>tasks.value.filter(t=>t.overdue));
const displayDate=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date());
let refreshSequence=0;
function clearWorkspace(){++refreshSequence;patients.value=[];tasks.value=[];reviews.value=[];bindings.value=[];health.value=null;capabilities.value=null;protocol.value=null;reviewId.value='';view.value='dashboard';refreshKey.value=0;}
async function refresh(){
  if(!auth.account||auth.account.role!=='clinician')return;
  const scope=authScope();const sequence=++refreshSequence;
  try{
    const [p,t,r,b,h,c,pr]=await Promise.all([api('/clinician/patients'),api('/clinician/tasks'),api('/clinician/reviews'),api('/clinician/bindings'),api('/health'),api('/clinician/voice/capabilities'),api('/clinician/protocol')]);
    if(!isCurrentAuth(scope)||sequence!==refreshSequence)return;
    patients.value=p.items;tasks.value=t.items;reviews.value=r.items;bindings.value=b.items;health.value=h;capabilities.value=c;protocol.value=pr;
  }catch(e){if(isCurrentAuth(scope)&&sequence===refreshSequence&&!isStaleAuthError(e))ElMessage.error((e as Error).message);}
}
async function changed(){refreshKey.value++;await refresh();}
function openReview(id:string){reviewId.value=id;view.value='reviews';}
async function logout(){try{await signOut();}catch(e){if(!isStaleAuthError(e)){ElMessage.error((e as Error).message);await refresh();}}}
async function approveProtocol(){const scope=authScope();try{const result=await ElMessageBox.prompt('请填写实际审核情况。批准代表您已核对采集问题、结束条件及紧急描述提示；详细草案请先查看项目中的采集协议说明。','确认采集协议',{inputType:'textarea',inputPlaceholder:'填写已完成的专业审核说明，至少10字',inputValidator:(v:string)=>v.trim().length>=10||'请填写实际审核说明',confirmButtonText:'记录审核并启用',cancelButtonText:'暂不启用'});assertCurrentAuth(scope);await api('/clinician/protocol/approve','POST',{note:result.value});assertCurrentAuth(scope);await refresh();}catch(e){if(isCurrentAuth(scope)&&e instanceof Error&&!isStaleAuthError(e))ElMessage.error(e.message);}}
let timer:ReturnType<typeof setInterval>|undefined;
function visible(){if(document.visibilityState==='visible')void refresh();}
onMounted(async()=>{await restoreAuth();timer=setInterval(()=>{if(document.visibilityState==='visible')void refresh();},30000);document.addEventListener('visibilitychange',visible);});
onUnmounted(()=>{clearInterval(timer);document.removeEventListener('visibilitychange',visible);});
// Login and logout can happen without reloading the document.
import {watch} from 'vue';
watch(()=>[auth.generation,auth.account?.id,auth.csrfToken],clearWorkspace,{flush:'sync'});
watch(()=>[auth.account?.id,auth.csrfToken],()=>{if(auth.account?.role==='clinician')void refresh();});
</script>
<template><div v-if="auth.loading" class="boot-screen"><span class="brand-mark">心</span><p>正在打开工作台…</p></div><LoginPanel v-else-if="!auth.account"/><div v-else :key="auth.generation" class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">心</span><div>心伴随访<small>医生工作台</small></div></div><div class="sidebar-label">随访协作</div><nav><button v-for="item in nav" :key="item.id" :class="{active:view===item.id}" @click="view=item.id"><el-icon><component :is="item.icon"/></el-icon><span>{{item.label}}</span><em v-if="item.id==='reviews'&&pendingReviews.length">{{pendingReviews.length}}</em><em v-if="item.id==='bindings'&&bindings.length">{{bindings.length}}</em></button></nav><div class="sidebar-note"><span class="note-dot"></span><div>患者在网页完成随访<small>记录在这里汇总与审核</small></div></div><div class="sidebar-account"><span class="avatar">{{auth.account.displayName.slice(-1)}}</span><div><strong>{{auth.account.displayName}}</strong><small>{{auth.account.role==='admin'?'管理员':'负责医生'}}</small></div><button aria-label="退出登录" class="icon-button" @click="logout"><el-icon><SwitchButton/></el-icon></button></div></aside><div class="main-frame"><header class="topbar"><div class="breadcrumb">心衰随访平台 <span>/</span> {{nav.find(n=>n.id===view)?.label}}</div><div class="topbar-right"><span>{{displayDate}}</span><button class="icon-button" aria-label="刷新数据" @click="changed"><el-icon><Refresh/></el-icon></button><button class="icon-button" aria-label="退出医生登录" @click="logout"><el-icon><SwitchButton/></el-icon></button></div></header><main><div v-if="health?.environment!=='production'&&health" class="environment-banner">开发联调环境 · {{health.collectionMode==='scripted'?'当前为本地流程采集，未调用 AI 模型':'已选择 AI 采集模式'}} · 请使用测试资料</div><div v-if="auth.account.role==='admin'" class="panel admin-message"><h2>管理员账户</h2><p>此账户用于平台初始化和管理。患者随访工作台请使用独立的医生账户登录。</p><el-button @click="logout">切换到医生账户</el-button></div><template v-else><template v-if="view==='dashboard'"><section class="page-heading"><div><span class="eyebrow">CARE CONTINUES</span><h1>您好，{{auth.account.displayName}}</h1><p>把今天需要跟进的事，放在一起。</p></div><div class="today-badge"><el-icon><Sunny/></el-icon> 每一次关心，都有记录</div></section><section class="stats-grid"><button class="stat-card" @click="view='patients'"><span>我的患者</span><strong>{{patients.length}}<small>人</small></strong><p>查看档案与网页账号 <span>↗</span></p></button><button class="stat-card" @click="view='tasks'"><span>待完成随访</span><strong>{{pendingTasks.length}}<small>次</small></strong><p>{{overdue.length?'其中 '+overdue.length+' 次已逾期':'按计划持续跟进'}} <span>↗</span></p></button><button class="stat-card accent" @click="view='reviews'"><span>等待您审核</span><strong>{{pendingReviews.length}}<small>份</small></strong><p>核对原话，给出反馈 <span>↗</span></p></button><a class="stat-card patient-entry-card" href="/patient/" target="_blank" rel="noopener noreferrer"><span>独立患者网站</span><strong>患者入口</strong><p>账号登录 · 语音随访 <span>↗</span></p></a></section><section class="dashboard-grid"><div class="panel"><div class="panel-toolbar"><h3>近期随访安排</h3><el-button text type="primary" @click="view='tasks'">查看全部 <el-icon><ArrowRight/></el-icon></el-button></div><el-table :data="pendingTasks.slice().sort((a,b)=>new Date(a.scheduled_at).getTime()-new Date(b.scheduled_at).getTime()).slice(0,6)" empty-text="暂无待完成的随访安排"><el-table-column label="患者" prop="name"/><el-table-column label="时间"><template #default="{row}">{{dateTime(row.scheduled_at)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><span class="status" :class="row.overdue?'orange':'gray'">{{row.overdue?'已逾期':taskLabel(row.status)}}</span></template></el-table-column></el-table></div><div class="panel"><div class="panel-toolbar"><h3>待审核记录</h3><span class="count">{{pendingReviews.length}}</span></div><div class="review-preview" v-for="r in pendingReviews.slice(0,5)" :key="r.id"><span class="avatar">{{r.name.slice(-1)}}</span><div><strong>{{r.name}}</strong><small>{{dateTime(r.submitted_at||r.started_at)}} · {{r.patient_confirmed?'已确认采集信息':'需要协助核对'}}</small></div><el-button text type="primary" @click="openReview(r.id)">查看 →</el-button></div><div v-if="!pendingReviews.length" class="quiet-empty"><span>✓</span><h3>暂时没有待审核记录</h3><p>患者提交后，会在这里显示。</p></div></div></section><div class="workflow-strip"><strong>随访如何连接起来</strong><span>医生建档、开通账号与安排</span><b>→</b><span>患者网页语音采集</span><b>→</b><span>医生审核与反馈</span></div></template><PatientWorkspace v-else-if="view==='patients'" :refresh-key="refreshKey" @changed="changed" @open-review="openReview"/><BindingWorkspace v-else-if="view==='bindings'" :refresh-key="refreshKey" @changed="changed"/><TaskWorkspace v-else-if="view==='tasks'" :refresh-key="refreshKey" @changed="changed"/><ReviewWorkspace v-else-if="view==='reviews'" :refresh-key="refreshKey" :initial-id="reviewId" @changed="changed"/><template v-else-if="view==='settings'"><section class="page-heading"><div><span class="eyebrow">SERVICE STATUS</span><h1>服务状态</h1><p>查看语音识别和助手播报服务的实际状态。</p></div></section><section class="panel settings-panel"><div class="service-row"><div><h3>服务器语音识别</h3><p>由服务器本地识别服务转写患者回答</p></div><span class="status" :class="capabilities?.asrStatus==='available'?'green':'orange'">{{capabilities?.asrStatus==='available'?'已检查，可连接':capabilities?.asrStatus==='unavailable'?'暂不可用，请联系管理员':capabilities?.asr?'已配置，尚未检查':'未获取可用状态'}}</span></div><div class="service-row"><div><h3>{{capabilities?.ttsMode==='server'?'服务器中文语音':capabilities?.ttsMode==='browser'?'浏览器声音':'云端语音合成'}}</h3><p>{{capabilities?.ttsMode==='browser'?'已选择患者设备的浏览器声音朗读问题，需在患者端检查声音和播放权限。':'让患者听到随访助手的问题，配置与实际播放需分别确认。'}}</p></div><span class="status" :class="capabilities?.ttsStatus==='available'?'green':'orange'">{{capabilities?.ttsMode==='browser'?'待患者设备检查':capabilities?.ttsStatus==='available'?'已检查，可连接':capabilities?.tts?'已配置，尚未检查':'暂不可用'}}</span></div><p v-if="capabilities?.message" class="muted">{{capabilities.message}}</p><div class="service-row"><div><h3>采集协议</h3><p>{{protocol?.version}} · 字段、问题及求助提示须由合作医生审核</p></div><span v-if="protocol?.approved_at" class="status green">已记录审核</span><el-button v-else @click="approveProtocol">记录审核并启用</el-button></div><div class="notice-card"><h3>当前采集协议草案</h3><div v-for="q in protocol?.questions||[]" :key="q.field"><strong>{{q.label}}</strong><p>{{q.question}}</p></div><p>{{protocol?.endingRule}}</p><p>{{protocol?.safetyRule}}</p></div><p class="muted">服务器可连接不代表患者设备已能录音和播放。麦克风授权、浏览器声音及实际效果需要在患者端检查。</p></section></template></template><footer class="page-footer">心伴随访 · 连接院后的每一份关心 <span>所有时间均为北京时间</span></footer></main></div></div></template>

<style scoped>
.patient-entry-card{text-decoration:none}.patient-entry-card strong{font-size:27px;letter-spacing:0;margin-top:19px;margin-bottom:19px}@media(max-width:760px){.patient-entry-card strong{font-size:23px;margin-top:16px;margin-bottom:16px}}
</style>
